-- Schema contract from the SaveRift round2 decoder importer; tests populate only synthetic rows.

CREATE TABLE IF NOT EXISTS r2_decode_runs(run_id TEXT PRIMARY KEY,results_path TEXT NOT NULL,results_sha256 TEXT,results_bytes INTEGER,imported_lines INTEGER,status TEXT,importer_version TEXT,importer_sha256 TEXT,updated_utc TEXT,summary_json TEXT);
CREATE TABLE IF NOT EXISTS r2_decode_documents(document_id TEXT PRIMARY KEY,run_id TEXT NOT NULL,payload_id TEXT NOT NULL,source_sha256 TEXT NOT NULL,output_sha256 TEXT NOT NULL,output_path TEXT,format TEXT,adapter TEXT,upstream_commit TEXT,source_json TEXT,quality_json TEXT,header_json TEXT);
CREATE TABLE IF NOT EXISTS r2_decode_attempts(run_id TEXT NOT NULL,line_number INTEGER NOT NULL,payload_id TEXT NOT NULL,source_sha256 TEXT,reported_status TEXT,status TEXT,document_id TEXT REFERENCES r2_decode_documents(document_id),record_sha256 TEXT NOT NULL,record_json TEXT NOT NULL,error TEXT,PRIMARY KEY(run_id,line_number));
CREATE INDEX IF NOT EXISTS r2_decode_attempt_payload ON r2_decode_attempts(run_id,payload_id,line_number);
CREATE TABLE IF NOT EXISTS r2_decode_structs(document_id TEXT NOT NULL REFERENCES r2_decode_documents(document_id),struct_hash TEXT NOT NULL,hash32 TEXT,hash64 TEXT,byte_size INTEGER,expected_instances INTEGER,emitted_instances INTEGER,role TEXT,schema_json TEXT NOT NULL,PRIMARY KEY(document_id,struct_hash));
CREATE TABLE IF NOT EXISTS r2_decode_fields(document_id TEXT NOT NULL,struct_hash TEXT NOT NULL,field_index INTEGER NOT NULL,field_hash TEXT,field_name TEXT,byte_offset INTEGER,field_type TEXT,field_subtype TEXT,reference_index INTEGER,extra_hex TEXT,is_array_element INTEGER,record_json TEXT NOT NULL,PRIMARY KEY(document_id,struct_hash,field_index),FOREIGN KEY(document_id,struct_hash) REFERENCES r2_decode_structs(document_id,struct_hash));
CREATE INDEX IF NOT EXISTS r2_decode_field_hash ON r2_decode_fields(field_hash);
CREATE TABLE IF NOT EXISTS r2_decode_instances(document_id TEXT NOT NULL,struct_hash TEXT NOT NULL,instance_index INTEGER NOT NULL,byte_offset INTEGER,object_json TEXT NOT NULL,PRIMARY KEY(document_id,struct_hash,instance_index),FOREIGN KEY(document_id,struct_hash) REFERENCES r2_decode_structs(document_id,struct_hash));
CREATE TABLE IF NOT EXISTS r2_decode_blocks(document_id TEXT NOT NULL REFERENCES r2_decode_documents(document_id),block_index INTEGER NOT NULL,struct_hash TEXT,byte_size INTEGER,byte_offset INTEGER,schema_known INTEGER,record_json TEXT,PRIMARY KEY(document_id,block_index));
CREATE VIEW IF NOT EXISTS r2_decode_latest AS SELECT a.* FROM r2_decode_attempts a WHERE NOT EXISTS(SELECT 1 FROM r2_decode_attempts b WHERE b.run_id=a.run_id AND b.payload_id=a.payload_id AND b.line_number>a.line_number);
CREATE VIEW IF NOT EXISTS r2_decode_current_instances AS SELECT a.run_id,a.payload_id,a.source_sha256,i.document_id,i.struct_hash,i.instance_index,i.byte_offset,i.object_json FROM r2_decode_latest a JOIN r2_decode_instances i ON i.document_id=a.document_id WHERE a.status='decoded_research';
